380	+
381	+/// One file the port serves at `path`.
382	+pub struct Page {
383	+    pub path: &'static str,
384	+    pub content_type: &'static str,
385	+    pub body: &'static str,
386	+}
387	+
388	+/// The files, matched by exact path. `index.html` declares a `data:`
389	+/// icon so a browser never asks for `/favicon.ico`.
390	+pub const PAGES: [Page; 3] = [
391	+    Page {
392	+        path: "/",
393	+        content_type: "text/html; charset=utf-8",
394	+        body: include_str!("../../web/index.html"),
395	+    },
396	+    Page {
397	+        path: "/app.js",
398	+        content_type: "text/javascript; charset=utf-8",
399	+        body: include_str!("../../web/app.js"),
400	+    },
401	+    Page {
402	+        path: "/app.css",
403	+        content_type: "text/css; charset=utf-8",
404	+        body: include_str!("../../web/app.css"),
405	+    },
406	+];
407	+
408	+/// What the page may load and talk to: its own files, its own API, and
409	+/// nothing else. No inline script or style, no framing, no form posts.
410	+/// `connect-src 'self'` is what admits `wss:` to the same host where a
411	+/// browser allows it; where one does not, the events socket is what is
412	+/// lost and polling carries.
413	+pub const CSP: &str = "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";
414	+
415	+/// The headers on every page reply, beyond the content type, length
416	+/// and `Connection: close` the writer adds.
417	+pub const HEADERS: [(&str, &str); 4] = [
418	+    ("Content-Security-Policy", CSP),
419	+    ("Cache-Control", "no-store"),
420	+    ("X-Content-Type-Options", "nosniff"),
421	+    ("Referrer-Policy", "no-referrer"),
422	+];
423	+
424	+/// The file at `path`, matched exactly; a query was already split off.
425	+#[must_use]
426	+pub fn page(path: &str) -> Option<&'static Page> {
427	+    PAGES.iter().find(|p| p.path == path)
428	+}
