1	/* The web control surface: one column, large touch targets, the
2	   waiting mark in words as well as colour. Light and dark follow the
3	   phone. */
4	
5	:root {
6	  color-scheme: light dark;
7	  --bg: #ffffff;
8	  --fg: #1a1a1a;
9	  --muted: #6b6b6b;
10	  --line: #e2e2e2;
11	  --card: #f6f6f6;
12	  --waiting: #b35c00;
13	  --waiting-bg: #fff3e6;
14	  --accent: #2d5bd1;
15	}
16	
17	@media (prefers-color-scheme: dark) {
18	  :root {
19	    --bg: #121212;
20	    --fg: #ececec;
21	    --muted: #9a9a9a;
22	    --line: #2c2c2c;
23	    --card: #1c1c1c;
24	    --waiting: #ffb366;
25	    --waiting-bg: #2a1d0f;
26	    --accent: #7fa3ff;
27	  }
28	}
29	
30	* { box-sizing: border-box; }
31	
32	html, body {
33	  margin: 0;
34	  background: var(--bg);
35	  color: var(--fg);
36	  font: 16px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
37	}
38	
39	#top {
40	  display: flex;
41	  align-items: center;
42	  gap: 12px;
43	  padding: 12px 16px;
44	  border-bottom: 1px solid var(--line);
45	  position: sticky;
46	  top: 0;
47	  background: var(--bg);
48	}
49	
50	#host-name { font-weight: 600; flex: 1; }
51	#scope { color: var(--muted); font-size: 14px; }
52	
53	main { padding: 12px 16px 32px; }
54	
55	button {
56	  font: inherit;
57	  color: var(--fg);
58	  background: var(--card);
59	  border: 1px solid var(--line);
60	  border-radius: 8px;
61	  padding: 10px 14px;
62	  min-height: 44px;
63	}
64	
