/// The name of the cookie a browser's token travels in: fixed to this
/// host by the `__Host-` prefix and to this installation by the
/// server id, so two instances on one address never read each
/// other's. The id survives a key rotation, so neither does a
/// rotation orphan it.
fn cookie_name(&self) -> Option<String> {
    self.core
        .identity()
        .map(|identity| format!("__Host-sb-{}", identity.server_id))
}

/// The paired device behind a request's credential, seen now; or
/// the refusal, which says nothing of the host. The credential is
/// the bearer header when present, else this host's cookie. A
/// request authenticated by the cookie alone that is not a plain
/// `GET` must come from the page's own origin: `SameSite=Strict`
/// withholds the cookie cross-site, and this closes the same-site,
/// other-port case. A bearer request is exempt, since a native
/// client sends no `Origin`.
fn authenticate(&mut self, request: &RemoteRequest) -> Result<PairedDevice, RemoteReply> {
    let by_cookie = request.bearer.is_none();
    let token = match &request.bearer {
        Some(token) => Some(token.clone()),
        None => request.cookie.as_deref().and_then(|header| {
            self.cookie_name()
                .and_then(|name| remote::cookie_value(header, &name))
        }),
    };
    let Some(token) = token else {
        return Err(self.refuse(
            request,
            401,
            "unauthorized",
            "pair this device first",
            false,
        ));
    };
    let Some(device) = self
        .core
        .device_by_token(&remote::token_sha256(&token))
        .cloned()
    else {
        return Err(self.refuse(
            request,
            401,
            "unauthorized",
            "the token is not known; pair again",
            false,
        ));
    };
    if by_cookie && (request.method != "GET" || request.upgrade.is_some()) {
        let expected = request
            .host
            .as_deref()
            .map(|host| format!("https://{host}"));
        if request.origin.is_none() || request.origin != expected {
