/// The headers on every reply, JSON or page, which no native client
/// reads and a browser does: not to be cached, not to be sniffed.
const STANDING_HEADERS: [(&str, &str); 2] = [
    ("Cache-Control", "no-store"),
    ("X-Content-Type-Options", "nosniff"),
];

/// Write one response. Head and body in one write, so a reply is one
/// TLS record and one segment. `connection` is what the connection does
/// next (`keep-alive` or `close`) and `headers` follow the standing
/// ones.
fn write_response<'a, W: Write>(
    w: &mut W,
    status: u16,
    content_type: &str,
    connection: &str,
    headers: impl IntoIterator<Item = (&'a str, &'a str)>,
    body: &[u8],
) -> io::Result<()> {
    let mut out = format!(
        "HTTP/1.1 {status} {}\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: {connection}\r\n",
        reason(status),
        body.len()
    );
    for (name, value) in STANDING_HEADERS.into_iter().chain(headers) {
        let _ = write!(out, "{name}: {value}\r\n");
    }
    out.push_str("\r\n");
    let mut out = out.into_bytes();
    out.extend_from_slice(body);
    w.write_all(&out)?;
    w.flush()
}

/// Write one JSON reply on a kept connection, with the reply's own
/// headers (a `Set-Cookie`) after the standing ones.
fn respond<W: Write>(w: &mut W, reply: &RemoteReply) -> io::Result<()> {
    let headers = reply.headers.iter().map(|(name, value)| (*name, value.as_str()));
    write_response(
        w,
        reply.status,
        "application/json",
        "keep-alive",
        headers,
        &reply.body,
    )
}

/// Write one of the web page's files, with the policy headers that keep
/// the page to itself, and close: a page load is a burst of short
/// requests from a stranger, and a kept connection would hold one of
/// the unauthenticated pool's four slots for the idle timeout.
fn respond_page<W: Write>(w: &mut W, page: &web::Page) -> io::Result<()> {
    write_response(
        w,
        200,
        page.content_type,
        "close",
        web::HEADERS,
        page.body.as_bytes(),
    )
}

