/// The pairing invite as the QR code and "Copy invite" carry it: the
/// page's URL with the code, the key hash and the server id in the
/// fragment. A fragment is never part of a request, so a server the
/// owner has not verified never receives the code; the page compares
/// the key and the id with `/info` before it sends anything. `address`
/// is the machine's local-network address, used only while the port
/// listens on the network; a Mac-only port is reached at loopback.
#[must_use]
pub fn invite_url(
    identity: &Identity,
    window: &PairingWindow,
    address: Option<IpAddr>,
    port: u16,
) -> String {
    let host = match address.filter(|_| identity.listen.lan) {
        Some(IpAddr::V6(ip)) => format!("[{ip}]"),
        Some(ip) => ip.to_string(),
        None => "127.0.0.1".to_owned(),
    };

input.new_string:
/// The address a phone reaches the port at: the machine's local-network
/// `address`, and only while the port listens on the network. `None`
/// means loopback, whether because the port is Mac-only or because no
/// network address was found; the dialog tells those apart by
/// `listen.lan`.
#[must_use]
pub fn reachable_address(identity: &Identity, address: Option<IpAddr>) -> Option<IpAddr> {
    address.filter(|_| identity.listen.lan)
}

/// The pairing invite as the QR code and "Copy invite" carry it: the
/// page's URL with the code, the key hash and the server id in the
/// fragment. A fragment is never part of a request, so a server the
/// owner has not verified never receives the code; the page compares
/// the key and the id with `/info` before it sends anything. The host
/// is [`reachable_address`], else loopback.
#[must_use]
pub fn invite_url(
    identity: &Identity,
    window: &PairingWindow,
    address: Option<IpAddr>,
    port: u16,
) -> String {
    let host = match reachable_address(identity, address) {
        Some(IpAddr::V6(ip)) => format!("[{ip}]"),
        Some(ip) => ip.to_string(),
        None => "127.0.0.1".to_owned(),
    };

