/// moved (the title, the mark, the text) and leave the compose box as
/// it is, with its draft, caret, focus and the phone's keyboard. A
/// refetch arrives every few seconds while an agent is active, and a
/// reply is typed exactly then. `provisional` is the text before the
/// content has loaded, or a content error; neither says anything
/// about whether the device may reply, so a footer already drawn
/// stays.
function renderSession(session, text, provisional) {
  const kind = footerKind(state.me, session, provisional);
  const view = state.view;
  if (view && view.session === session.id) {
    view.title.textContent = session.name;
    setMark(view.mark, session);
    view.pre.textContent = text;
    const next = kind === 'none' ? view.kind : kind;
    // The compose box is rebuilt only when it first appears; the
    // other two footers are a line of text that may have changed.
    if (next !== 'compose' || view.kind !== 'compose') fillFooter(view, next, session);
    return;
  }
  clear();
  back.hidden = false;
  const title = el('h2', null, session.name);
  const mark = el('p', 'mark', '');
  setMark(mark, session);
  const pre = el('pre', 'text', text);
  const footer = el('div', 'footer');
  screen.appendChild(title);
  screen.appendChild(mark);
  screen.appendChild(el('p', 'small',
    session.kind === 'claude' ? 'Last response' : 'Screen'));
  screen.appendChild(pre);
  screen.appendChild(footer);
  state.view = { session: session.id, title, mark, pre, footer, kind: 'none' };
  fillFooter(state.view, kind, session);
}

function setMark(mark, session) {
  const reason = session.waiting_reason ? ': ' + session.waiting_reason : '';
  mark.textContent = session.waiting ? 'Waiting on you' + reason : '';
  mark.hidden = !session.waiting;
}

function fillFooter(view, kind, session) {
  view.kind = kind;
  const footer = view.footer;
  while (footer.firstChild) footer.removeChild(footer.firstChild);
  if (kind === 'readonly') {
    footer.appendChild(el('p', 'small', 'This device reads only. Raise its scope on the Mac to reply.'));
    return;
  }
  if (kind === 'refusal') {
    footer.appendChild(el('p', 'small', session.prompt_refusal));
    return;
  }
  if (kind !== 'compose') return;
  const compose = el('div', 'compose');
  const box = document.createElement('textarea');
  box.placeholder = 'Reply…';
  if (state.pending && state.pending.session === session.id) box.value = state.pending.text;
  const status = el('div', 'status', '');
  const send = el('button', 'primary', 'Send');
  send.type = 'button';
  send.addEventListener('click', () => sendReply(session, box, send, status));
  compose.appendChild(box);
  compose.appendChild(send);
  compose.appendChild(status);
